Grid StudyGrid(int n,int refinement){auto mesh=cubed_sphere::CompositeMesh(.25,{.45,.55,.60,.65,.70,.75,1},1,n,3,2);if(refinement)mesh=h::RefinePunctureNeighborhood(std::move(mesh),h::PuncturePosition{},refinement,50000).mesh;if(mesh.blocks.size()*size_t(n)*n*n>50000)throw std::runtime_error("study cell budget");return Grid(std::move(mesh),4,true);}
std::vector<Datum> StudyInitial(const std::string &path,const Grid&g){std::ifstream f(path);std::string magic;size_t count;f>>magic>>count;if(magic!="ISOTROPIC_M1_3"||count!=g.active.size())throw std::runtime_error("initial shape mismatch");std::vector<Datum> rows(count);for(size_t p=0;p<count;++p){auto&d=rows[p];f>>d.r>>d.chi>>d.alpha>>d.arr>>d.khat;if(!f||std::abs(d.r-Radius(g.geometry[p].x))>2e-13)throw std::runtime_error("initial radius mismatch");}return rows;}
S FD6(const Grid&g,const V&values,int field,size_t p,bool full_chain=true){S out{};const int point=field*g.count+g.active[p];out.value=values[point];Real d[3]{},dd[3][3]{};auto w=[](int a){return a==0?Real(0):(std::abs(a)==1?Real(3*a)/4:(std::abs(a)==2?Real(-3*a)/40:Real(a)/180));};
 for(int a=0;a<3;++a){for(int i=-3;i<=3;++i)if(i)d[a]+=g.n*w(i)*(values[point+g.Offset(a,i)]-values[point]);for(int b=0;b<3;++b){if(a==b){for(int i=-3;i<=3;++i)if(i){const Real c=std::abs(i)==1?1.5:(std::abs(i)==2?-.15:1./90);dd[a][b]+=g.n*g.n*c*(values[point+g.Offset(a,i)]-values[point]);}}else for(int i=-3;i<=3;++i)if(i)for(int j=-3;j<=3;++j)if(j)dd[a][b]+=g.n*g.n*w(i)*w(j)*(values[point+g.Offset(a,i)+g.Offset(b,j)]-values[point+g.Offset(a,i)]-values[point+g.Offset(b,j)]+values[point]);}}
 const auto &geometry=g.geometry[p];for(int a=0;a<3;++a)for(int A=0;A<3;++A){out.d[a]+=geometry.J[A][a]*d[A];for(int b=0;b<3;++b){if(full_chain)out.dd[a][b]+=geometry.H[A][a][b]*d[A];for(int B=0;B<3;++B)out.dd[a][b]+=geometry.J[A][a]*geometry.J[B][b]*dd[A][B];}}return out;}
S ReplaceSix(Engine&engine,const Grid &g,const V&padded,size_t p,int f){const auto&x=g.geometry[p].x;const S stored=FD6(g,padded,f==0?0:1,p);S physical{};if(engine.PositiveChart(f,x).Reconstruct(stored,physical)!=h::PositiveFieldStatus::valid)throw std::runtime_error("order6 reconstruction failed");return physical;}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{if(argc<6)throw std::runtime_error("catalog initial catalog n refinement OR diagnose initial exact n refinement output");const auto start=std::chrono::steady_clock::now();const int n=std::stoi(argv[4]),refinement=std::stoi(argv[5]);auto grid=StudyGrid(n,refinement);const auto initial=StudyInitial(argv[2],grid);std::cout<<std::setprecision(17);
 if(std::string(argv[1])=="catalog"){std::ofstream out(argv[3]);out<<std::setprecision(17)<<"kind,id,x,y,z,r\n";auto emit=[&](int kind,size_t id,const Real*x){out<<kind<<','<<id<<','<<x[0]<<','<<x[1]<<','<<x[2]<<','<<Radius(x)<<'\n';};for(size_t p=0;p<grid.active.size();++p)emit(0,p,grid.geometry[p].x);size_t ghosts=0;for(const auto&row:grid.halos){const auto x=PaddedPoint(grid,row.target);if(Radius(x.data())>0&&Radius(x.data())<.85){emit(2,row.target,x.data());++ghosts;}}const Real mid[3]={.5,0,0},scri[3]={1,0,0};emit(1,1,mid);emit(1,0,scri);std::cout<<"{\"cells\":"<<initial.size()<<",\"ghosts\":"<<ghosts<<",\"ng\":3}\n";}
 else if(std::string(argv[1])=="diagnose"){
  if(argc!=7)throw std::runtime_error("missing diagnostic output");const auto exact=ReadExact(argv[3]);auto baseline_mesh=grid.mesh;baseline_mesh.ghosts=2;Engine engine(std::move(baseline_mesh),true,1e-10,4,true,true,0,6,true,2,.24,true,true,true,true,.24,1);engine.Initialize(0,false);engine.InitializeWormhole(argv[2],0,false);const V state=engine.state,original=engine.Padded(state);engine.GeometryJets(state,original);const auto baseline=engine.jets;const auto &old=engine.shift.grid;
  V padded(2*grid.count);for(size_t p=0;p<initial.size();++p){padded[grid.active[p]]=state[22*p];padded[grid.count+grid.active[p]]=state[22*p+18];}
  std::map<Point,V> boundary_cache;grid.Fill(padded,2,[&](int f,const auto&x){auto found=boundary_cache.find(x);if(found==boundary_cache.end())found=boundary_cache.emplace(x,engine.scri->Interpolate(engine.scri->values,22,x.data())).first;return found->second[f==0?0:18];});
  for(int m=0;m<int(grid.mesh.blocks.size());++m)for(int k=-2;k<n+2;++k)for(int j=-2;j<n+2;++j)for(int i=-2;i<n+2;++i){const int now=grid.Index(m,i,j,k),before=old.Index(m,i,j,k);padded[now]=original[before];padded[grid.count+now]=original[18*old.count+before];}
  auto oracle=padded;for(const auto&item:exact)if(item.first.first==2){const int index=item.first.second;const auto x=PaddedPoint(grid,index);oracle[index]=StoredExact(x.data(),item.second,0).value;oracle[grid.count+index]=StoredExact(x.data(),item.second,1).value;}
  std::vector<bool> selected(initial.size(),false);if(engine.supported_log_plans)for(const auto &row:engine.supported_log_plans->Rows())selected[row.active]=true;
  auto fourth_scalar=[&](size_t p,int f){S stored{};const int component=f==0?0:1;stored.value=oracle[component*grid.count+grid.active[p]];Real d[3],dd[3][3];grid.Derivatives(oracle,component,p,d,dd);for(int a=0;a<3;++a){stored.d[a]=d[a];for(int b=0;b<3;++b)stored.dd[a][b]=dd[a][b];}S physical{};if(engine.PositiveChart(f,grid.geometry[p].x).Reconstruct(stored,physical)!=h::PositiveFieldStatus::valid)throw std::runtime_error("fourth oracle decode");return physical;};
  std::ofstream out(argv[6]);out<<std::setprecision(17)<<"point,block,face,layer,i,j,k,x,y,z,r,weight,method,chi_d_error,chi_dd_error,alpha_d_error,alpha_dd_error,H,M";for(int f=0;f<24;++f)out<<",dq"<<f;out<<'\n';
  const char*methods[]={"fourth_default","fourth_exact_halos","sixth_transition","sixth_transition_exact_halos","all_analytic"};size_t replacements=0;Real polynomial[3][3]{},constant=0;
  // Independent mapped Cartesian constant/linear/quadratic controls. Exact
  // physical polynomial samples at ALL ghost locations avoid halo error.
  V manufactured(3*grid.count);for(int m=0;m<int(grid.mesh.blocks.size());++m)for(int k=-3;k<n+3;++k)for(int j=-3;j<n+3;++j)for(int i=-3;i<n+3;++i){const int index=grid.Index(m,i,j,k);const auto x=PaddedPoint(grid,index);manufactured[index]=1;manufactured[grid.count+index]=x[0]+.3*x[1]-.7*x[2];manufactured[2*grid.count+index]=x[0]*x[0]+.7*x[0]*x[1]-.2*x[1]*x[2]+2*x[2]*x[2];}
  for(size_t p=0;p<initial.size();++p){const auto &x=grid.geometry[p].x;const int block=p/(n*n*n);const bool transition=grid.mesh.blocks[block].layer==0;const auto truthjet=Analytic({x[0],x[1],x[2]},exact.at({0,p}));const auto truth=Quantities(engine,truthjet,{x[0],x[1],x[2]});if(transition){++replacements;for(int f=0;f<3;++f){S exactp{};if(f==1){exactp.d[0]=1;exactp.d[1]=.3;exactp.d[2]=-.7;}if(f==2){exactp.d[0]=2*x[0]+.7*x[1];exactp.d[1]=.7*x[0]-.2*x[2];exactp.d[2]=4*x[2]-.2*x[1];exactp.dd[0][0]=2;exactp.dd[2][2]=4;exactp.dd[0][1]=exactp.dd[1][0]=.7;exactp.dd[1][2]=exactp.dd[2][1]=-.2;}for(int rule=0;rule<3;++rule){S observed{};if(rule==0){Real d[3],dd[3][3];grid.Derivatives(manufactured,f,p,d,dd);for(int a=0;a<3;++a){observed.d[a]=d[a];for(int b=0;b<3;++b)observed.dd[a][b]=dd[a][b];}}else observed=FD6(grid,manufactured,f,p,rule==1);for(int a=0;a<3;++a){polynomial[rule][f]=std::max(polynomial[rule][f],std::abs(observed.d[a]-exactp.d[a]));for(int b=0;b<3;++b)polynomial[rule][f]=std::max(polynomial[rule][f],std::abs(observed.dd[a][b]-exactp.dd[a][b]));}if(f==0)constant=std::max(constant,polynomial[rule][f]);}}}
   for(int method=0;method<5;++method){U u=baseline[p];u.beta=truthjet.beta;if((method==1||method==3)&&!selected[p]){u.chi=fourth_scalar(p,0);u.alpha=fourth_scalar(p,18);}if((method==2||method==3)&&transition){for(int a=0;a<3;++a)for(int i=-3;i<=3;++i){const auto sample=PaddedPoint(grid,grid.active[p]+grid.Offset(a,i));if(!(Radius(sample.data())>0&&Radius(sample.data())<.85))throw std::runtime_error("sixth transition stencil outside oracle contract");}u.chi=ReplaceSix(engine,grid,method==3?oracle:padded,p,0);u.alpha=ReplaceSix(engine,grid,method==3?oracle:padded,p,18);}if(method==4)u=truthjet;
    Real dg=0,dh=0,ag=0,ah=0;for(int a=0;a<3;++a){dg=std::max(dg,std::abs(u.chi.d[a]-truthjet.chi.d[a]));ag=std::max(ag,std::abs(u.alpha.d[a]-truthjet.alpha.d[a]));for(int b=0;b<3;++b){dh=std::max(dh,std::abs(u.chi.dd[a][b]-truthjet.chi.dd[a][b]));ah=std::max(ah,std::abs(u.alpha.dd[a][b]-truthjet.alpha.dd[a][b]));}}
    const auto values=Quantities(engine,u,{x[0],x[1],x[2]});out<<p<<','<<block<<','<<grid.mesh.blocks[block].face<<','<<grid.mesh.blocks[block].layer<<','<<p%n<<','<<p/n%n<<','<<p/(n*n)%n<<','<<x[0]<<','<<x[1]<<','<<x[2]<<','<<Radius(x)<<','<<grid.volumes[p]/std::pow(truthjet.chi.value,1.5)<<','<<methods[method]<<','<<dg<<','<<dh<<','<<ag<<','<<ah<<','<<values[0]<<','<<values[1];for(int f=0;f<24;++f)out<<','<<values[f]-truth[f];out<<'\n';if(n==6&&refinement==3&&p==126)std::cout<<"{\"phase\":\"target\",\"method\":\""<<methods[method]<<"\",\"H\":"<<values[0]<<",\"chi_d_error\":"<<dg<<",\"chi_dd_error\":"<<dh<<",\"lapse_d_error\":"<<ag<<",\"lapse_dd_error\":"<<ah<<"}\n";
   }
  }
  std::cout<<"{\"phase\":\"summary\",\"n\":"<<n<<",\"refinement\":"<<refinement<<",\"cells\":"<<initial.size()<<",\"transition_cells\":"<<replacements<<",\"ng\":3,\"original_ng2_halo_cache_preserved\":true,\"third_halo_layer_ordinary_interpolation\":true,\"physical_polynomial_max_errors_fourth_sixth_noH\":[";for(int i=0;i<3;++i){if(i)std::cout<<',';std::cout<<'['<<polynomial[i][0]<<','<<polynomial[i][1]<<','<<polynomial[i][2]<<']';}std::cout<<"],\"constant_error_max\":"<<constant<<",\"active_values_unchanged\":true,\"production_adopted\":false,\"seconds\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<"}\n";
 }else throw std::runtime_error("unknown mode");
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=1;}Kokkos::finalize();return code;}
